/**
 * Part 3 of the narrator: what she says when you go somewhere (round 69).
 *
 * One entry per thing the visitor can go to or open: the arrival, the Sun,
 * every planet and dwarf planet, the notable moons and small bodies by
 * name, a line for each family that covers everything else, every
 * dashboard topic, every space event, the ultraviolet views and the
 * galactocentric view. A few lines each for a body, plain words, the character of the
 * thing rather than its statistics.
 *
 * The same text is what she is recorded saying (docs/voice-script.md, Part
 * 3, generated from this file) and can be shown on screen, so the words and
 * the voice always agree. Entries are in recording order: `rec` is the
 * recording they belong to, and their order within it is the order they are
 * spoken, which is how the recordings are cut back into lines.
 *
 * Facts are the site's own (its dossiers and captions) or standard values;
 * where something is a nickname or debated, the line says so.
 */
export const NARRATION = [
  // ===== 3A · Arrival, the Sun and the planets ==============================
  { rec: "3A", id: "arrival-1", text: "One star, eight planets — and at least five dwarf planets, with more found every few years." },
  { rec: "3A", id: "arrival-2", text: "All of it condensed out of one collapsing cloud of gas and dust, four point six billion years ago." },
  { rec: "3A", id: "arrival-3", text: "You are ten light-years out, looking back in." },
  /*
   * The one line about the guided tour (guidedTour.js). Spoken as the tour
   * opens after the arrival, and only then: the tour runs once, so a visitor
   * who finished or skipped it before never hears it, and pressing "Skip
   * tour" stops it mid-sentence. No tour step has a line of its own.
   */
  { rec: "3A", id: "tour-invite", text: "Before you set off, take the short tour. It shows you how to fly, how to find any world on the board, the dictionary of space words, the real events that happen out here, and the view from the Milky Way. Or skip it, and explore on your own." },
  { rec: "3A", id: "Sun", text: "This is the Sun, our star. More than a million Earths could fit inside it, and it holds almost all the mass of everything you will see here. Every planet is still falling around it." },
  { rec: "3A", id: "Mercury", text: "This is Mercury, the smallest planet and the closest to the Sun. Its year lasts just eighty-eight days — yet one day, from sunrise to sunrise, lasts a hundred and seventy-six." },
  { rec: "3A", id: "Venus", text: "This is Venus, the hottest planet of all — even though Mercury is closer to the Sun. Its thick clouds trap the heat, hot enough to melt lead. And it spins backwards, so here the Sun rises in the west." },
  { rec: "3A", id: "Earth", text: "This is Earth. Our home — the only place we know of where life exists. Oceans cover most of it, and a thin blue layer of air keeps every one of us alive." },
  { rec: "3A", id: "Moon", text: "This is the Moon, Earth's companion, and the fifth largest moon in the Solar System. It always shows us the same face — and it is slowly drifting away, about four centimetres every year." },
  { rec: "3A", id: "Mars", text: "This is Mars, the red planet — red because its dust is full of rust. It holds the tallest volcano in the Solar System, Olympus Mons, about two and a half times the height of Everest." },
  { rec: "3A", id: "Jupiter", text: "This is Jupiter, the giant — more than twice the mass of all the other planets put together. Its gravity catches and flings away many comets and asteroids, which is why it is often called Earth's shield. And its Great Red Spot is a storm bigger than our whole planet." },
  { rec: "3A", id: "Saturn", text: "This is Saturn, the jewel of the Solar System. Its rings are made of countless pieces of ice, some as small as grains of sand, some as big as houses. And the planet itself is so light, it would float in a bathtub big enough to hold it." },
  { rec: "3A", id: "Uranus", text: "This is Uranus, the planet that rolls around the Sun on its side. Something huge knocked it over long ago — so each pole gets forty-two years of sunlight, then forty-two years of night." },
  { rec: "3A", id: "Neptune", text: "This is Neptune, the farthest planet — so far that sunlight takes four hours to reach it. It has the fastest winds in the Solar System, more than two thousand kilometres an hour." },

  // ===== 3B · Dwarf planets and the moons ===================================
  { rec: "3B", id: "Ceres", text: "This is Ceres, the largest thing in the asteroid belt, and the only dwarf planet there. Bright patches of salt shine on its surface — left behind by salty water that rose up from below." },
  { rec: "3B", id: "Pluto", text: "This is Pluto. Once the ninth planet, now the most famous dwarf planet of all. It has a giant heart-shaped glacier of frozen nitrogen — and a moon so big that the two of them swing around each other." },
  { rec: "3B", id: "Eris", text: "This is Eris, almost exactly Pluto's size, but heavier. Its discovery started the great debate that ended with Pluto no longer being called a planet." },
  { rec: "3B", id: "Haumea", text: "This is Haumea, the egg-shaped dwarf planet. It spins so fast — once in under four hours — that it has stretched itself out. It was also the first world beyond Neptune found to have a ring." },
  { rec: "3B", id: "Makemake", text: "This is Makemake, a bright dwarf planet beyond Neptune, coated in frozen methane. It was found just after Easter, and named after the creator god of Easter Island." },
  { rec: "3B", id: "Gonggong", text: "This is Gonggong, one of the biggest and reddest worlds beyond Neptune, named after a Chinese water god. One trip around the Sun takes it about five hundred and fifty years." },
  { rec: "3B", id: "Quaoar", text: "This is Quaoar, a world beyond Neptune with a puzzle around it: a ring sitting far outside the distance where a ring should survive. By the usual rules, it should have clumped together into a moon." },
  { rec: "3B", id: "Orcus", text: "This is Orcus, sometimes called the anti-Pluto. It moves in the same rhythm with Neptune as Pluto does — but always on the opposite side of the Sun." },
  { rec: "3B", id: "Sedna", text: "This is Sedna, one of the most distant worlds we know. Its long, stretched orbit takes more than eleven thousand years — and even at its closest, it never comes near Neptune." },
  { rec: "3B", id: "Ixion", text: "This is Ixion, a large icy world that keeps time with Neptune — two of its laps for every three of Neptune's, the same beat as Pluto." },
  { rec: "3B", id: "Salacia", text: "This is Salacia, a dark, icy world in the Kuiper Belt with a moon of its own, Actaea. It is named after the Roman goddess of the salt sea." },
  { rec: "3B", id: "Varuna", text: "This is Varuna, a big Kuiper Belt world that turns once every six hours — fast enough to squash itself into an egg shape." },
  { rec: "3B", id: "Varda", text: "This is Varda, named after the queen of the stars in Tolkien's legends. Its moon, Ilmarë, is named after one of her spirits, and the two circle each other far beyond Neptune." },
  { rec: "3B", id: "Ganymede", text: "This is Ganymede, the largest moon in the Solar System — bigger than the planet Mercury. It is the only moon with a magnetic field of its own, and it may hide an ocean beneath its ice." },
  { rec: "3B", id: "Titan", text: "This is Titan, Saturn's largest moon, and the second largest in the Solar System. It is the only moon with a thick atmosphere — and the only place besides Earth with lakes on its surface. Lakes of liquid methane." },
  { rec: "3B", id: "Callisto", text: "This is Callisto, the third largest moon, and the most cratered world we know. Its surface has barely changed in four billion years — a perfect record of the early Solar System." },
  { rec: "3B", id: "Io", text: "This is Io, the fourth largest moon, and the most volcanic world in the Solar System. Jupiter squeezes it like a stress ball, and the heat bursts out through hundreds of volcanoes." },
  { rec: "3B", id: "Europa", text: "This is Europa, the sixth largest moon. Under its shell of ice lies a salty ocean holding more water than all of Earth's oceans — one of the best places to look for life beyond Earth." },
  { rec: "3B", id: "Triton", text: "This is Triton, Neptune's giant moon, and the seventh largest in the Solar System. It orbits backwards, so it was probably captured — and it has geysers that blow dark plumes kilometres into the sky." },
  { rec: "3B", id: "Titania", text: "This is Titania, Uranus's largest moon, and the eighth largest in the Solar System — cut by canyons hundreds of kilometres long." },
  { rec: "3B", id: "Rhea", text: "This is Rhea, Saturn's second largest moon, and the ninth largest in the Solar System — a cold, cratered ball made mostly of ice." },
  { rec: "3B", id: "Oberon", text: "This is Oberon, the outermost of Uranus's big moons, and the tenth largest in the Solar System — old, dark and covered in craters." },
  { rec: "3B", id: "Iapetus", text: "This is Iapetus, the two-faced moon. One side is as dark as coal, the other as bright as snow — and a ridge of mountains runs around its middle, like the seam of a walnut." },
  { rec: "3B", id: "Charon", text: "This is Charon, Pluto's great moon, half Pluto's size. The two always face each other, locked together like a pair of dancers." },
  { rec: "3B", id: "Umbriel", text: "This is Umbriel, the darkest of Uranus's big moons — quiet and ancient, with one bright ring-shaped mark on its face." },
  { rec: "3B", id: "Ariel", text: "This is Ariel, the brightest of Uranus's big moons, criss-crossed by long valleys from a time when its surface was still young." },
  { rec: "3B", id: "Dione", text: "This is Dione, a moon of Saturn streaked with bright cliffs of ice, hundreds of metres tall, where its frozen crust has cracked." },
  { rec: "3B", id: "Tethys", text: "This is Tethys, a moon made almost entirely of water ice, with a canyon that runs three-quarters of the way around it." },
  { rec: "3B", id: "Enceladus", text: "This is Enceladus, one of the brightest objects in the Solar System. From its south pole, jets of salty water shoot out into space, from an ocean hidden under the ice." },
  { rec: "3B", id: "Miranda", text: "This is Miranda, the patchwork moon of Uranus — pieced together from wildly different landscapes, with cliffs twenty kilometres tall, the highest known anywhere." },
  { rec: "3B", id: "Mimas", text: "This is Mimas, the little moon with one enormous crater — so big for its size that Mimas looks like a giant eye staring back at you." },
  { rec: "3B", id: "Hyperion", text: "This is Hyperion, a moon that looks like a sponge, and tumbles so chaotically that no one can predict which way it will face next." },
  { rec: "3B", id: "Phoebe", text: "This is Phoebe, a dark moon that circles Saturn backwards, far out — probably a visitor from the outer Solar System that Saturn captured long ago." },
  { rec: "3B", id: "Janus", text: "This is Janus. It shares its orbit with another moon, Epimetheus — and every four years the two swap places, in a slow cosmic dance." },
  { rec: "3B", id: "Epimetheus", text: "This is Epimetheus. It shares its orbit with Janus — and every four years the two trade places, without ever touching." },
  { rec: "3B", id: "Pan", text: "This is Pan, a tiny moon living in a gap in Saturn's rings, shaped like a flying saucer by the ring dust piling up around its middle." },
  { rec: "3B", id: "Daphnis", text: "This is Daphnis, a little moon that makes waves. As it orbits inside a gap in the rings, it pulls the ring edges into rippling peaks." },
  { rec: "3B", id: "Amalthea", text: "This is Amalthea, a small, potato-shaped moon close to Jupiter — one of the reddest objects in the Solar System." },
  { rec: "3B", id: "Himalia", text: "This is Himalia, the largest of Jupiter's far-out moons — probably a captured asteroid, leading a family of smaller moons that share its path." },
  { rec: "3B", id: "Proteus", text: "This is Proteus, Neptune's second largest moon — about as big as a moon can be without pulling itself into a ball." },
  { rec: "3B", id: "Nereid", text: "This is Nereid, a moon of Neptune on one of the most stretched-out orbits of any moon, swinging from near to far and back over almost a year." },
  { rec: "3B", id: "Phobos", text: "This is Phobos, the larger of Mars's two tiny moons. It orbits so close that it rises in the west and sets in the east — and it is slowly spiralling in. One day, it will break apart." },
  { rec: "3B", id: "Deimos", text: "This is Deimos, the smaller and farther of Mars's moons, only about twelve kilometres across. From Mars it would look like a bright star." },
  { rec: "3B", id: "Dysnomia", text: "This is Dysnomia, the moon of Eris — named after the daughter of the goddess of discord." },

  // ===== 3C · Small bodies by name ==========================================
  { rec: "3C", id: "Vesta", text: "This is Vesta, the brightest asteroid — sometimes you can see it without a telescope. A giant impact near its south pole blasted out pieces that still fall to Earth as meteorites." },
  { rec: "3C", id: "Pallas", text: "This is Pallas, one of the biggest asteroids, on an orbit tilted steeply to all the others — a world that refuses to stay in line." },
  { rec: "3C", id: "Hygiea", text: "This is Hygiea, a large, dark asteroid, so round that it may be a dwarf planet itself." },
  { rec: "3C", id: "Psyche", text: "This is Psyche, an asteroid rich in metal — perhaps part of the core of a world that never finished forming. A spacecraft of the same name is on its way to see it." },
  { rec: "3C", id: "Kleopatra", text: "This is Kleopatra, a metal asteroid shaped like a dog's bone, with two little moons of its own." },
  { rec: "3C", id: "Sylvia", text: "This is Sylvia, the first asteroid found with two moons — a little system of three." },
  { rec: "3C", id: "Interamnia", text: "This is Interamnia, one of the largest asteroids of all — and no spacecraft has ever visited it." },
  { rec: "3C", id: "Bennu", text: "This is Bennu, a loose pile of rubble shaped like a spinning top. A spacecraft touched it, grabbed a sample and brought it home to Earth." },
  { rec: "3C", id: "Ryugu", text: "This is Ryugu, another spinning-top rubble pile. A Japanese spacecraft brought back pieces of it — about fifty times more than it planned." },
  { rec: "3C", id: "Itokawa", text: "This is Itokawa, a little asteroid shaped like a peanut — two piles of gravel resting together, with lots of empty space inside." },
  { rec: "3C", id: "Eros", text: "This is Eros, the first asteroid a spacecraft ever orbited — and then landed on." },
  { rec: "3C", id: "Apophis", text: "This is Apophis. On the thirteenth of April, twenty twenty-nine, it will pass closer to Earth than many of our satellites — close enough to see without a telescope. It will not hit us." },
  { rec: "3C", id: "Didymos", text: "This is Didymos, and the little moon going round it, Dimorphos. In twenty twenty-two, a spacecraft crashed into the moon on purpose — the first time people ever changed the path of another world." },
  { rec: "3C", id: "Arrokoth", text: "This is Arrokoth, the most distant object a spacecraft has ever visited. It is two flattened lumps that touched gently and stuck — like a snowman made in space." },
  { rec: "3C", id: "Ida", text: "This is Ida, the first asteroid ever found to have a moon of its own — little Dactyl." },
  { rec: "3C", id: "Gaspra", text: "This is Gaspra, the first asteroid ever photographed up close, by a spacecraft on its way to Jupiter." },
  { rec: "3C", id: "Mathilde", text: "This is Mathilde, a dark asteroid so light for its size that it must be full of holes." },
  { rec: "3C", id: "Lutetia", text: "This is Lutetia, one of the densest asteroids ever measured — far heavier than it looks." },
  { rec: "3C", id: "Phaethon", text: "This is Phaethon, a rock that behaves like a comet. Every December, Earth runs through the dust it leaves behind — and we see it as the Geminid meteor shower." },
  { rec: "3C", id: "Cruithne", text: "This is Cruithne, sometimes called Earth's second moon — but it is not a moon. It circles the Sun, and only seems to loop around us." },
  { rec: "3C", id: "Kamoʻoalewa", text: "This is Kamoʻoalewa, a little rock that travels alongside Earth around the Sun — perhaps a piece of our own Moon, blasted off long ago." },
  { rec: "3C", id: "Toutatis", text: "This is Toutatis, an asteroid that does not spin neatly — it tumbles end over end as it goes." },
  { rec: "3C", id: "Ganymed", text: "This is Ganymed — not the moon, but the largest of the asteroids that come near Earth, about thirty-eight kilometres long." },
  { rec: "3C", id: "2021 PH27", text: "This is the asteroid that gets closer to the Sun than any other known — its surface heats to about five hundred degrees, and its year lasts just a hundred and thirteen days." },
  { rec: "3C", id: "Hektor", text: "This is Hektor, the largest of Jupiter's Trojans — two lumps joined together, travelling ahead of Jupiter on its own orbit." },
  { rec: "3C", id: "Patroclus", text: "This is Patroclus and its partner, Menoetius — two almost equal worlds circling each other, trailing behind Jupiter." },
  { rec: "3C", id: "Hilda", text: "This is Hilda, which gives its name to a family of asteroids that keep a perfect rhythm with Jupiter — three laps for every two of Jupiter's." },
  { rec: "3C", id: "Chariklo", text: "This is Chariklo, a small icy world between the giant planets — and the first thing that is not a planet found to have rings." },
  { rec: "3C", id: "Chiron", text: "This is Chiron. When it was found, it was called an asteroid — then it grew a glowing cloud like a comet. It turned out to be both." },
  { rec: "3C", id: "Pholus", text: "This is Pholus, one of the reddest objects ever measured in the Solar System." },
  { rec: "3C", id: "Echeclus", text: "This is Echeclus, a quiet icy world that once suddenly flared up, hundreds of times brighter than normal." },
  { rec: "3C", id: "1P/Halley", text: "This is Halley's Comet, the most famous comet of all. It comes back about every seventy-six years — next in twenty sixty-one." },
  { rec: "3C", id: "C/1995 O1 Hale-Bopp", text: "This is Hale-Bopp, the great comet of nineteen ninety-seven. People could see it without a telescope for a year and a half." },
  { rec: "3C", id: "C/2020 F3 NEOWISE", text: "This is comet NEOWISE, which lit up the summer sky in twenty twenty — the brightest comet in the northern sky in more than twenty years." },
  { rec: "3C", id: "67P/Churyumov–Gerasimenko", text: "This is the comet a spacecraft followed for two whole years — and even landed on. It is shaped like a rubber duck." },
  { rec: "3C", id: "C/2014 UN271", text: "This is the largest comet nucleus ever found — over a hundred kilometres across — falling in from the Oort Cloud, at the edge of the Solar System." },
  { rec: "3C", id: "2P/Encke", text: "This is Comet Encke, which comes back more often than any other bright comet — every three point three years." },
  { rec: "3C", id: "12P/Pons-Brooks", text: "This is Pons-Brooks, nicknamed the devil comet, because its outbursts once gave it what looked like a pair of horns." },
  { rec: "3C", id: "9P/Tempel 1", text: "This is Tempel 1, the comet a spacecraft hit on purpose, to see what lies beneath its surface." },
  { rec: "3C", id: "81P/Wild 2", text: "This is Wild 2, the first comet whose dust was caught and brought back to Earth." },

  // ===== 3D · Families: the line for everything without its own ===========
  { rec: "3D", id: "family:moon", text: "This is one of the many small moons of the Solar System — a world too small to pull itself round, circling a planet far bigger than itself." },
  { rec: "3D", id: "family:provisional-moon", text: "This moon does not have a name yet, only a catalogue number. It was found so recently that it is still waiting to be named." },
  { rec: "3D", id: "family:jupiter-inner", text: "This is one of Jupiter's small inner moons, racing round just outside its faint rings. Dust knocked off moons like this one is what the rings are made of." },
  { rec: "3D", id: "family:jupiter-irregular", text: "This is one of Jupiter's many little outer moons — mostly captured asteroids, far from the planet, many of them going round backwards." },
  { rec: "3D", id: "family:saturn-norse", text: "This is one of Saturn's Norse moons — small, dark and far out, nearly all going round backwards. Saturn has more moons than any other planet." },
  { rec: "3D", id: "family:saturn-inuit", text: "This is one of Saturn's Inuit moons — small reddish rocks on distant, tilted orbits, named after the giants of Inuit legend." },
  { rec: "3D", id: "family:saturn-gallic", text: "This is one of Saturn's Gallic moons — small reddish rocks on tilted outer orbits, named after the giants of Celtic legend." },
  { rec: "3D", id: "family:saturn-ring", text: "This is one of the little moons among Saturn's rings. Its gravity herds the ring particles, and keeps the edges of the rings sharp." },
  { rec: "3D", id: "family:saturn-trojan", text: "This is one of Saturn's Trojan moons. It shares its orbit with a bigger moon, riding along sixty degrees ahead of it, or behind." },
  { rec: "3D", id: "family:uranus-inner", text: "This is one of Uranus's small inner moons, packed so tightly that some of them may collide in the next few million years." },
  { rec: "3D", id: "family:uranus-irregular", text: "This is one of Uranus's distant outer moons — captured long ago, and most of them going round backwards." },
  { rec: "3D", id: "family:neptune-inner", text: "This is one of Neptune's small inner moons, circling close to its faint, clumpy rings." },
  { rec: "3D", id: "family:neptune-irregular", text: "This is one of Neptune's far-flung outer moons. Some of them take decades to go round just once." },
  { rec: "3D", id: "family:pluto-small", text: "This is one of Pluto's four little moons. They tumble wildly as they circle Pluto and Charon together." },
  { rec: "3D", id: "family:dwarf-moon", text: "This is the moon of a small world far beyond Neptune. Moons like this one let us weigh the worlds they circle." },
  { rec: "3D", id: "family:asteroid", text: "This is an asteroid — a rocky leftover from the time the planets were built. Millions of them circle the Sun between Mars and Jupiter." },
  { rec: "3D", id: "family:asteroid-c", text: "This is a dark, carbon-rich asteroid, the most common kind — as dark as charcoal, and almost unchanged since the Solar System began." },
  { rec: "3D", id: "family:asteroid-s", text: "This is a stony asteroid, made of the same kind of rock as many of the meteorites that land on Earth." },
  { rec: "3D", id: "family:asteroid-m", text: "This is a metal-rich asteroid — perhaps a piece of the iron heart of a small world that broke apart." },
  { rec: "3D", id: "family:nea-atira", text: "This asteroid belongs to the Atiras, which stay inside Earth's orbit the whole way round. They are so close to the Sun that we can only spot them in twilight." },
  { rec: "3D", id: "family:nea-aten", text: "This asteroid belongs to the Atens — its year is shorter than ours, and its path crosses Earth's." },
  { rec: "3D", id: "family:nea-apollo", text: "This asteroid belongs to the Apollos, the biggest family of near-Earth rocks. Its path crosses Earth's orbit — which is why astronomers keep watching it." },
  { rec: "3D", id: "family:nea-amor", text: "This asteroid belongs to the Amors. They come close to Earth, but never cross its orbit." },
  { rec: "3D", id: "family:trojan-jupiter", text: "This is one of Jupiter's Trojans — rocks gathered at two calm spots on Jupiter's orbit, one ahead of the planet and one behind." },
  { rec: "3D", id: "family:trojan-inner", text: "This rock shares a planet's orbit, riding a calm spot sixty degrees ahead of it or behind — a Trojan of the inner Solar System." },
  { rec: "3D", id: "family:trojan-outer", text: "This is a Trojan of the outer planets, sharing the orbit of Uranus or Neptune at one of its two calm spots." },
  { rec: "3D", id: "family:centaur", text: "This is a Centaur — an icy world caught between the giant planets. It is on its way in from beyond Neptune, and one day it may become a comet." },
  { rec: "3D", id: "family:comet", text: "This is a comet — a frozen lump of ice and dust. Far from the Sun it is dark and asleep. Close to it, it wakes up, and grows a glowing head and tail." },
  { rec: "3D", id: "family:tno", text: "This is one of the icy worlds beyond Neptune, in the cold, dim outskirts of the Solar System, where the Sun is just a bright star." },
  { rec: "3D", id: "family:binary", text: "These are two worlds going round each other, as they travel round the Sun together." },
  { rec: "3D", id: "region:termination-shock", text: "Here, the solar wind hits the brakes. It has rushed out from the Sun at a million miles an hour — and now it suddenly slows down." },
  { rec: "3D", id: "region:heliosheath", text: "This is the heliosheath, where the slowed-down solar wind piles up and swirls, before it finally runs out." },
  { rec: "3D", id: "region:heliopause", text: "This is the heliopause — where the Sun's wind finally gives way to the wind between the stars. Two Voyager spacecraft have crossed it." },
  { rec: "3D", id: "region:inner-oort", text: "This is the inner Oort Cloud, a vast doughnut of icy bodies, reaching far beyond everything we have seen." },
  { rec: "3D", id: "region:outer-oort", text: "This is the Oort Cloud, a shell of perhaps a trillion comets surrounding the Solar System. No one has ever seen it — we know it is there because of the comets that fall in from it." },
  { rec: "3D", id: "region:plutinos", text: "These are the Plutinos — Pluto and the worlds that move in step with Neptune, two orbits for every three of Neptune's." },
  { rec: "3D", id: "region:classical-belt", text: "This is the classical Kuiper Belt, a wide band of icy worlds on calm, round orbits beyond Neptune." },
  { rec: "3D", id: "region:kuiper-cliff", text: "This is the Kuiper Cliff. Here the Kuiper Belt suddenly stops — and nobody yet knows why." },
  { rec: "3D", id: "region:scattered-disc", text: "This is the scattered disc — icy worlds that Neptune threw outward long ago, onto long, stretched orbits." },
  { rec: "3D", id: "region:detached", text: "These are the detached worlds, so far out that even Neptune cannot reach them. Something else put them there, and we do not know what." },

  // ===== 3E · The ultraviolet views and Venus by radar =====================
  { rec: "3E", id: "uv:intro", text: "This is ultraviolet light, which our eyes cannot see. Switched to it, the aurora shines out — just as ultraviolet cameras record it, in false colour." },
  { rec: "3E", id: "uv:Mercury", text: "Mercury has almost no air, so it has no glowing aurora — but when the solar wind strikes it, it shines in X-rays instead." },
  { rec: "3E", id: "uv:Venus", text: "Venus has no magnetic field of its own, yet it still glows. The solar wind lights up its upper air in a faint, patchy aurora." },
  { rec: "3E", id: "uv:Mars", text: "Mars lost its global magnetic field long ago, but pieces of it remain in its rocks — and above them, small patches of aurora light up." },
  { rec: "3E", id: "uv:Jupiter", text: "Jupiter has the most powerful aurora in the Solar System — brighter than the whole Earth, and fed by volcanic gas from its moon Io." },
  { rec: "3E", id: "uv:Saturn", text: "Saturn's aurora is a glowing ring around each pole, brightening and dimming as the solar wind gusts." },
  { rec: "3E", id: "uv:Uranus", text: "Uranus's magnetic field is tipped far over, so its aurora does not sit on its poles — it wanders across the planet." },
  { rec: "3E", id: "uv:Neptune", text: "Neptune's aurora was finally caught in twenty twenty-five — glowing far from its poles, because its magnetic field is tilted so far." },
  { rec: "3E", id: "uv:Io", text: "Even Io has an aurora. Its thin volcanic air glows as Jupiter's magnetic field sweeps past it." },
  { rec: "3E", id: "uv:Europa", text: "Europa's thin air glows faintly as Jupiter's magnetism washes over it — hints of the ocean below." },
  { rec: "3E", id: "uv:Ganymede", text: "Ganymede has aurorae of its own, and the way they rock back and forth is the evidence for a salty ocean hidden beneath its ice." },
  { rec: "3E", id: "uv:Callisto", text: "Callisto's thin air glows faintly too, as Jupiter's magnetic field sweeps across it." },
  { rec: "3E", id: "uv:67P", text: "This was the first aurora ever found around a comet — glowing in ultraviolet, as the solar wind struck its thin cloud of gas." },
  { rec: "3E", id: "venus-radar", text: "Beneath the clouds of Venus lies a surface no eye has ever seen directly. Radar mapped it — volcanoes, lava plains and mountains, hidden under the thickest air of any rocky planet." },

  /*
   * ===== 3F · The deep part: explainers, the galactocentric view, the events ==
   * Round 69, later (the owner: "space events we can have a good amount of
   * vocal"): these are longer — four to eight sentences, about 30-45 s —
   * because each opens a view the visitor sits and watches. Facts are those on
   * the views' own cards (explainers/*.js, jupiterCompanyView.js,
   * galactocentricView.js, solarSystemEvents.js, systemProcesses.js,
   * interstellarPassages.js, spaceEventsDashboard.js).
   */
  { rec: "3F", id: "topic:jupiter-company", text: "Jupiter does not travel alone. Look at the two great swarms of rocks on its path — one sixty degrees ahead of it, one sixty degrees behind. These are the Trojans, more than eleven thousand of them. At those two spots, the pull of the Sun and the pull of Jupiter balance just right, so a rock there keeps pace with the giant for ever. Jupiter is always heading for the ones in front, the ones behind are always following — and no one ever catches up. They have waited there for billions of years. Closer in are the Hildas. They go round the Sun three times for every two of Jupiter's laps, timed so that whenever Jupiter passes, they are far away. Seen from Jupiter, their paths trace a slowly turning triangle." },
  { rec: "3F", id: "topic:tidal-locking", text: "Why do we only ever see one face of the Moon? The Moon does spin — but it turns exactly once each time it goes around Earth, every twenty-seven days. So the same side always faces us. It was not always this way. Long ago, the young Moon spun faster. Earth's gravity stretched it slightly into an egg shape, and Earth's pull on that bulge acted like a brake, slowing its spin until the two rhythms matched. Then the braking stopped: the Moon was locked. Nearly every big moon in the Solar System has done the same. And the Moon is doing it to us, too — every century, our day grows about two thousandths of a second longer. No one saw the far side of the Moon until nineteen fifty-nine." },
  { rec: "3F", id: "topic:centaurs", text: "Between Jupiter and Neptune, there are no safe orbits. Yet more than a thousand icy worlds wander here. They are the Centaurs — named after the half-human, half-horse creatures of legend, because they are half asteroid, half comet. They began beyond Neptune, until Neptune nudged them inward. Now the giant planets pass them along like a ball — Uranus, Saturn, Jupiter. None of them stays long: a few million years, a blink in the life of the Solar System. Some are thrown out towards the stars. Others are pushed further in, warm up, and become comets. And they come in two colours — grey, or deep red. Nobody yet knows why." },
  { rec: "3F", id: "topic:laplace", text: "Watch Jupiter's three big moons keep time. For every lap Ganymede makes around Jupiter, Europa makes exactly two, and Io makes exactly four. Because the rhythm repeats, the moons keep meeting at the same places, and every meeting gives the same small tug. The tugs add up, and keep their orbits slightly stretched. And strangely, all three can never line up together on the same side of Jupiter. This clockwork is what makes Io the most volcanic world we know. Jupiter squeezes it, then lets go, again and again, and its ground rises and falls by about a hundred metres. The same squeezing keeps Europa's hidden ocean from freezing." },
  { rec: "3F", id: "topic:inner-trojans", text: "Every planet has two calm spots on its path — one sixty degrees ahead of it, one sixty degrees behind — where a small rock can ride along at exactly the planet's pace. Venus has one known Trojan there. Earth has two. Mars has seventeen. But having the spots is not the same as keeping anything in them. Mars's Trojans have stayed for billions of years — and most of them are broken-off pieces of one rock, called Eureka. Earth's and Venus's are only visitors. They drift in, ride along with us for a while, and drift away again." },
  { rec: "3F", id: "topic:outer-trojans", text: "Out among the giants, the same trick works. Neptune has forty-two known Trojans, riding sixty degrees ahead of it and behind, and they have been there for billions of years. Uranus has just two, and they are only passing through. And Saturn? Not a single one has ever been found. Long ago, Jupiter's pull and the wandering of the young giant planets swept Saturn's calm spots clean." },
  { rec: "3F", id: "topic:kirkwood", text: "The asteroid belt looks like a smooth ring of rocks. But count the asteroids by the size of their orbits, and it has holes in it. These are the Kirkwood gaps, first noticed in eighteen sixty-six. Each gap is a place where a rock would keep time with Jupiter — three laps for every one of Jupiter's, or five for every two. Meeting Jupiter at the same spot again and again, it gets pushed the same way every time, until it is flung out of the belt altogether. Some of those rocks are sent towards Earth — which is why so many of the meteorites that land here came from these gaps. And some asteroids belong to families: the broken pieces of one bigger rock, shattered in a collision, still travelling on almost the same path." },
  { rec: "3F", id: "topic:heliosheath", text: "Out here, more than twelve billion kilometres from the Sun, the solar wind finally runs out of push. It has rushed out at about a million miles an hour — and at the termination shock, it suddenly slows down. Beyond it, in the heliosheath, the wind piles up, heats up and swirls, pressed back by the thin wind that blows between the stars. Then comes the heliopause — the edge of the Sun's bubble. Both Voyager spacecraft have crossed it, and they are still sending back word from interstellar space." },
  { rec: "3F", id: "topic:nea-atira", text: "The Atiras are the rarest near-Earth family — only thirty-eight are known. They never leave Earth's orbit: they circle the Sun entirely inside it. That keeps them close to the Sun in our sky, so they can only be searched for in twilight, at dusk or dawn. That is why so few have been found — not because they are rare out in space. Living so close to the Sun, they are baked: one of them heats to about five hundred degrees." },
  { rec: "3F", id: "topic:nea-aten", text: "The Atens go round the Sun in less than a year. Their orbits are smaller than ours, but stretched enough to cross out past Earth's path. More than three thousand are known. Most are small, a few hundred metres across, and many spin fast — Hathor turns in under three and a half hours. Two famous neighbours are Atens: Apophis, which will pass close to Earth in twenty twenty-nine, and Cruithne, which travels a horseshoe-shaped path alongside us." },
  { rec: "3F", id: "topic:nea-apollo", text: "The Apollos are the biggest near-Earth family — more than twenty-four thousand are known. Their orbits are bigger than Earth's, but they dip inside it, crossing our path. They come in every shape: potatoes, spinning tops, and two lumps resting together. About one in six has a little moon of its own. Two of them, Bennu and Ryugu, have been visited by spacecraft that brought pieces home — and the dust from Bennu holds some of the building blocks of life." },
  { rec: "3F", id: "topic:nea-amor", text: "The Amors come close to Earth, but never cross our path — their nearest point to the Sun lies just outside Earth's orbit. Nearly fifteen thousand are known, and the biggest near-Earth asteroids are Amors: Ganymed, about thirty-eight kilometres across, Don Quixote, and Eros. Among them is a mountain of solid metal, called nineteen eighty-six DA. And Don Quixote turned out to be something else entirely — a sleeping comet." },
  { rec: "3F", id: "topic:binaries", text: "Not every world travels alone. These two go round a shared balance point between them, as they journey round the Sun together. Pairs like this are surprisingly common. Among near-Earth asteroids, about one in six has a moon, and far beyond Neptune, many worlds come in twos. And watching them circle each other is how we weigh them." },
  { rec: "3F", id: "topic:comet-glow", text: "A comet spends most of its life as a dark, frozen lump, far from the Sun. But as it falls closer, sunlight warms its ice, and the ice turns straight into gas. The gas carries dust out with it, and a glowing cloud grows around the comet — its head. Then the Sun pushes it all back into tails: a curving, golden tail of dust, and a straight blue tail of gas, blown by the solar wind. Both always point away from the Sun — even when the comet is heading back out again." },
  { rec: "3F", id: "galacto-1", text: "The Sun is not standing still. It is racing around the centre of our galaxy at about two hundred and thirty kilometres every second — more than eight hundred thousand kilometres every hour. And it takes everything with it: every planet, every moon, every comet. So the planets do not really move in circles. They follow the Sun in long spirals, like a corkscrew through the stars. Right now, we are all heading towards the constellation Cygnus, the Swan." },
  { rec: "3F", id: "galacto-2", text: "One lap around the Milky Way takes about two hundred and thirty million years. That is a galactic year. Earth is about twenty galactic years old. One lap ago, the first dinosaurs were just appearing. We live about twenty-six thousand light-years from the centre, where a black hole four million times the mass of the Sun sits hidden behind clouds of dust. And as we go round, the Sun also bobs gently up and down through the galaxy's disc, like a horse on a carousel." },
  { rec: "3F", id: "event:solar-system-formation", text: "Four point six billion years ago, there was no Sun — only a cold, dark cloud of gas and dust. It began to collapse under its own gravity. As it fell inwards it spun faster, and flattened into a disc. At the centre, the Sun switched on. Out in the disc, dust grains stuck together into pebbles, pebbles into boulders, boulders into small worlds — and the small worlds crashed together into planets. We can still watch this happening today, around young stars, where telescopes find flat discs of dust with dark rings carved by newborn planets." },
  { rec: "3F", id: "event:solar-wind", text: "The Sun never stops blowing. Its outer atmosphere, the corona, is over a million degrees — too hot for even the Sun's gravity to hold. So it streams away into space as a wind of charged particles, more than a million tonnes every second. Because the Sun turns as it blows, the wind is twisted into a giant spiral, like water from a spinning garden sprinkler. It flows out past every planet, until, far beyond Neptune, the wind between the stars finally stops it." },
  { rec: "3F", id: "event:solar-cme", text: "Sometimes the Sun does more than blow. Its magnetic field gets twisted up, tighter and tighter, until a loop suddenly snaps — and hurls a billion tonnes of glowing plasma into space, at up to three thousand kilometres a second. This is a coronal mass ejection. The fastest ones reach Earth in less than a day. When one hits us, our magnetic shield shakes, satellites and power grids feel it, and the northern and southern lights spread far from the poles. In May twenty twenty-four, one of these storms painted aurora across skies that almost never see them." },
  { rec: "3F", id: "event:sungrazer", text: "Some comets dive almost straight into the Sun. Most of them belong to one family, the Kreutz sungrazers — pieces of a single giant comet that broke apart centuries ago, still arriving one at a time on the same path. A spacecraft watching the Sun finds one every few days. They pass within a whisker of the Sun's surface, and almost none survive. The small ones simply boil away. In twenty thirteen, Comet ISON went in whole, and came out as dust. Often, all that is left is the glowing tail — outliving the comet that made it." },
  { rec: "3F", id: "event:mercury-sodium-tail", text: "Mercury, the little planet closest to the Sun, has a tail — just like a comet. The solar wind and tiny meteorites knock sodium atoms off its surface, and then sunlight itself pushes them away, into a faint, glowing stream about twenty-four million kilometres long. It shines the same orange-yellow as old sodium street lights. And it grows strongest twice in every orbit, as Mercury speeds up and slows down near the Sun." },
  { rec: "3F", id: "event:meteor-shower", text: "On the same nights every year, the sky fills with shooting stars. Comets leave trails of dust along their paths, and Earth's orbit crosses those trails at the same places each year. Each grain, often no bigger than a grain of sand, hits our air at tens of kilometres a second, and burns up in a streak of light. The Perseids each August come from comet Swift–Tuttle. The Geminids each December come from the rock Phaethon. There are about a dozen major showers a year — all you need is a dark sky, and patience." },
  { rec: "3F", id: "event:solar-eclipse", text: "The Sun is about four hundred times wider than our Moon — and, by pure chance, about four hundred times farther away. So from Earth, the two look almost exactly the same size. When the Moon passes exactly in front of the Sun, its shadow falls on Earth and races across it, at more than seventeen hundred kilometres an hour. Inside that shadow, day turns to night for a few minutes, the stars come out, and the Sun's glowing outer atmosphere appears around a black disc. Any one place on Earth waits, on average, about three hundred and seventy-five years to see it." },
  { rec: "3F", id: "event:seasons", text: "Many people think summer comes when Earth is closer to the Sun. It does not. Earth is closest to the Sun in early January — in the middle of northern winter. The seasons come from tilt. Earth's axis leans about twenty-three and a half degrees, and it keeps pointing the same way as we go round the Sun. For half the year, the north leans towards the Sun, with long days and high sunshine. For the other half, the south does. On Uranus, tipped right over on its side, each season lasts twenty-one years." },
  { rec: "3F", id: "event:earth-magnetosphere", text: "Deep inside Earth, molten iron churns, and makes a magnetic field. It surrounds our planet like an invisible shield, turning aside the solar wind that would otherwise wear away our air. When a storm from the Sun strikes, the shield is squeezed and shaken. Energy pours down near the poles, and the air there glows green and red — the aurora. Other planets have shields too. Jupiter's is so huge that, if we could see it, it would look bigger than the full Moon in our sky." },
  { rec: "3F", id: "event:lunar-impact-flash", text: "Earth's air protects us from small space rocks — they burn up as shooting stars. The Moon has no air at all. So the same little rocks, many no bigger than a pebble, hit its ground at tens of kilometres a second. All that speed turns into heat in an instant, and makes a flash of light bright enough to see from Earth through a telescope. Each flash lasts less than a tenth of a second. Watchers catch about one every hour and a half. The rocks hit the whole Moon — but we can only see the flashes on its dark side." },
  { rec: "3F", id: "event:mars-dust-storm", text: "Mars is a dusty planet, and every Martian year brings dust storms. But every few Earth years, one of them refuses to die. Sunlight warms the dust in the air, the warm air drives stronger winds, the winds lift more dust — and the storm feeds itself, until it wraps around the entire planet. From space, the surface of Mars disappears for weeks. In twenty eighteen, one of these storms blotted out the sunlight that powered the Opportunity rover. After almost fifteen years exploring Mars, it never woke up again." },
  { rec: "3F", id: "event:jupiter-impact", text: "Jupiter is the Solar System's great target. Its huge gravity pulls in stray asteroids, comets and icy wanderers from every direction. Rocks just a few metres across strike it tens of times a year. They never reach the ground — Jupiter has none. They explode high in its clouds in a flash of light, and leave nothing behind. Amateur astronomers, filming Jupiter from their backyards, catch one of these flashes every year or so. And in nineteen ninety-four, the whole world watched the pieces of comet Shoemaker–Levy nine slam into Jupiter, leaving dark scars bigger than Earth." },
  { rec: "3F", id: "event:io-eruption", text: "Io is the most volcanic world we know. It has around four hundred active volcanoes, and at every moment, something is erupting. Some throw fountains of sulphur three hundred kilometres up into space, in great umbrella-shaped plumes that fall back as frost. The heat comes from Jupiter: Io is squeezed and stretched by its giant planet on every orbit. So much lava pours out that Io's whole surface is repainted every few thousand years. Its yellows, oranges and reds are not rock — they are sulphur." },
  { rec: "3F", id: "event:saturn-impact", text: "Saturn gets hit too — though less often than Jupiter, perhaps a fifth as often, because it is smaller and farther out. Most of what strikes it are icy wanderers falling in from beyond Neptune. Nobody has yet confirmed seeing a flash on Saturn. But its rings remember. The Cassini spacecraft found ripples in them, left by a cloud of debris that struck them in nineteen eighty-three — when no one was watching." },
  { rec: "3F", id: "event:saturn-white-spot", text: "About once every thirty years — once in each Saturn year — a giant storm bursts out on Saturn. For decades, heat and water vapour build up deep beneath its clouds, trapped under lighter air. Then, all at once, they break through. A bright white storm appears, and spreads along its band until it wraps right round the planet. The last one, in twenty ten, was the biggest ever recorded. It raged for months, and changed Saturn's atmosphere for years afterwards." },
  { rec: "3F", id: "event:ring-spokes", text: "Look closely at Saturn's rings, and sometimes you will see ghostly spokes — dark smudges thousands of kilometres long, lying across the rings like the spokes of a wheel. They appear, and fade, within hours. They should be impossible: the inner part of the rings goes round faster than the outer part, so a straight line should be smeared away in minutes. The secret is electricity. Tiny grains of ice pick up a charge, lift off the rings, and are carried round by Saturn's magnetic field instead. They come in seasons — and right now, it is spoke season." },
  { rec: "3F", id: "event:enceladus-plumes", text: "Enceladus is a small moon, only about five hundred kilometres across — but beneath its icy shell lies a whole ocean. Saturn's pull flexes the moon and keeps the water from freezing. At the south pole, four long cracks in the ice, nicknamed the tiger stripes, let it escape. More than a hundred jets spray water out into space. Some falls back as snow. The rest drifts away and becomes one of Saturn's rings. The Cassini spacecraft flew right through the spray and tasted it: salt, sand-like silica, and carbon-rich molecules. It is one of the best places to look for life beyond Earth." },
  { rec: "3F", id: "event:uranus-storms", text: "For years, Uranus looked like a calm, blank ball. When Voyager 2 flew past in nineteen eighty-six, it saw almost nothing at all. That is because Uranus lies on its side. For decades, one pole faces the Sun while the other sits in darkness, and the weather goes quiet. But as Uranus moves along its orbit, sunlight returns to both halves, and the storms wake up. In twenty fourteen, telescopes counted eight big storms in a single night — bright enough for backyard astronomers to see." },
  { rec: "3F", id: "event:triton-geysers", text: "Triton is one of the coldest places ever measured — just thirty-eight degrees above absolute zero. And yet it has geysers. Faint sunlight shines through clear nitrogen ice and warms the darker ground beneath it. The nitrogen there turns to gas, pressure builds, and it bursts out, carrying dark dust eight kilometres high. Then the thin wind catches each plume, and streams it out a hundred and fifty kilometres. Voyager 2 saw them in nineteen eighty-nine — and no spacecraft has been back since." },
  { rec: "3F", id: "event:oumuamua-passage", text: "In twenty seventeen, astronomers spotted something strange, already on its way out of our Solar System. It had come from another star. It was moving far too fast for the Sun to hold, on a path that falls in once, swings round the Sun, and leaves for ever. They named it ʻOumuamua — a Hawaiian word for a scout, a messenger from far away. We never saw it as more than a point of light, flickering as it tumbled. And it sped up slightly as it left, with no gas or dust to show why. It is still a mystery." },
  { rec: "3F", id: "event:borisov-passage", text: "Two years later came the second visitor from another star — and this one was a comet. It was found by Gennadiy Borisov, an amateur astronomer, using a telescope he had built himself. As the Sun warmed it, it grew a glowing head and tail, just like our own comets. But its gas was different: it held far more carbon monoxide than any comet born here. For the first time, we were tasting the ice of another solar system." },
  { rec: "3F", id: "event:atlas-3i-passage", text: "In twenty twenty-five came the third visitor — and the fastest ever recorded. Even before the Sun's pull sped it up, it was moving at fifty-eight kilometres every second — so fast that its path through our Solar System is almost a straight line. It came from the direction of the centre of our galaxy, and it may be older than the Sun itself. As it passed Mars, spacecraft there — and even a rover on the Martian ground — photographed it. Now it is heading back out to the stars, never to return." },
  { rec: "3F", id: "event:supernova", text: "When a giant star — at least eight times heavier than our Sun — runs out of fuel, its heart collapses in less than a second. The rest of the star crashes inwards, rebounds, and explodes. For weeks, that one dying star can outshine its whole galaxy of billions. The blast scatters the elements forged inside it — oxygen, silicon, iron — out into space, where they become part of new stars, and new planets. The oxygen you are breathing was made in stars like this. Our galaxy has about two supernovae every century, but most are hidden from us behind dust." },
  { rec: "3F", id: "event:kilonova", text: "When a giant star explodes, it can leave behind a neutron star — a ball only about twenty kilometres across, but heavier than the Sun. A teaspoon of it would weigh as much as a mountain. Sometimes two of them circle each other, closer and closer, until they crash together. That collision is a kilonova. In a few seconds, it forges gold, platinum and other heavy elements, and flings them into space. In twenty seventeen, we saw one for the first time — and felt it too, as ripples in space itself. Much of the gold on Earth was made this way." },
  // ===== 3G · More named worlds (round 69, the coverage check) ===========
  { rec: "3G", id: "Juno", text: "This is Juno, the third asteroid ever found, back in eighteen oh four — and one of the largest in the whole belt." },
  { rec: "3G", id: "52 Europa", text: "This is Europa — not Jupiter's moon, but an asteroid with the same name. It is one of the biggest in the belt, dark and rich in carbon." },
  { rec: "3G", id: "Davida", text: "This is Davida, one of the largest asteroids of all — a dark, rounded world about three hundred kilometres across." },
  { rec: "3G", id: "Eunomia", text: "This is Eunomia, the biggest stony asteroid of all, and the parent of a whole family of smaller pieces that share its path." },
  { rec: "3G", id: "Cybele", text: "This is Cybele, a large, dark asteroid out at the far edge of the main belt, where it gives its name to a little group of rocks." },
  { rec: "3G", id: "Camilla", text: "This is Camilla, a big, dark asteroid beyond the main belt, with two small moons of its own." },
  { rec: "3G", id: "Kalliope", text: "This is Kalliope, a metal-rich asteroid with a large moon called Linus — named after her son, in Greek legend." },
  { rec: "3G", id: "Linus", text: "This is Linus, the moon of the asteroid Kalliope — nearly thirty kilometres across, which is big for an asteroid's moon." },
  { rec: "3G", id: "Themis", text: "This is Themis, a dark asteroid where astronomers found frost — water ice, right on the surface of an asteroid." },
  { rec: "3G", id: "Flora", text: "This is Flora, the parent of one of the largest asteroid families — and possibly the source of many of the meteorites that land on Earth." },
  { rec: "3G", id: "Romulus", text: "This is Romulus, the larger of the two moons of the asteroid Sylvia — named after one of the twin founders of Rome." },
  { rec: "3G", id: "Remus", text: "This is Remus, the smaller of Sylvia's two moons — named after Romulus's twin brother." },
  { rec: "3G", id: "Dactyl", text: "This is Dactyl, the first moon ever found around an asteroid. It circles Ida, and it is barely a kilometre and a half across." },
  { rec: "3G", id: "Dimorphos", text: "This is Dimorphos, the little moon that a spacecraft crashed into on purpose, in twenty twenty-two. The impact shortened its orbit by thirty-two minutes — proof that we can push a dangerous rock off course." },
  { rec: "3G", id: "Dinkinesh", text: "This is Dinkinesh, a tiny asteroid that the Lucy spacecraft flew past in twenty twenty-three. Lucy found it has a moon — and that moon is two rocks stuck together." },
  { rec: "3G", id: "Selam", text: "This is Selam, the moon of Dinkinesh — two little rocks resting against each other, the first moon of its kind ever found." },
  { rec: "3G", id: "Donaldjohanson", text: "This is Donaldjohanson, named after the scientist who found Lucy, the famous fossil of an early human ancestor. The Lucy spacecraft flew past it in twenty twenty-five, and found a long, strange shape." },
  { rec: "3G", id: "19P/Borrelly", text: "This is Comet Borrelly, shaped like a bowling pin. A spacecraft called Deep Space One photographed it up close in two thousand and one." },
  { rec: "3G", id: "103P/Hartley 2", text: "This is Comet Hartley 2, small and peanut-shaped. A spacecraft flew past it in twenty ten, and found it blasting out jets of gas and chunks of ice." },
  { rec: "3G", id: "Don Quixote", text: "This is Don Quixote. It looks like an asteroid that comes near Earth — but in two thousand and nine, a space telescope caught it breathing out gas. It is a sleeping comet." },
  { rec: "3G", id: "Puck", text: "This is Puck, the largest of Uranus's small inner moons, discovered by Voyager 2 in nineteen eighty-five." },
  { rec: "3G", id: "Galatea", text: "This is Galatea, a little moon of Neptune. Its gravity gathers Neptune's outermost ring into bright clumps, called arcs." },
  { rec: "3G", id: "Larissa", text: "This is Larissa, a small, battered moon of Neptune, very slowly spiralling in towards the planet." },
  { rec: "3G", id: "Vanth", text: "This is Vanth, the large moon of Orcus — named after an Etruscan spirit who guided souls into the underworld." },
  { rec: "3G", id: "Hi'iaka", text: "This is Hiʻiaka, the larger of Haumea's two moons, named after a Hawaiian goddess — one of Haumea's daughters." },
  { rec: "3G", id: "Namaka", text: "This is Namaka, the smaller of Haumea's two moons, named after a Hawaiian water spirit — another of Haumea's daughters." },
  { rec: "3G", id: "MK 2", text: "This is the little dark moon of Makemake, found by the Hubble telescope in twenty sixteen, hiding in its parent's glare." },
  { rec: "3G", id: "Huya", text: "This is Huya, an icy world that keeps time with Neptune just as Pluto does, with a moon of its own. It is named after the rain spirit of the Wayuu people of South America." },
  { rec: "3G", id: "Máni", text: "This is Máni, about eight hundred kilometres across — one of the largest worlds beyond Neptune that no spacecraft has seen. It is named after the Moon, in Norse legend." },
  { rec: "3G", id: "Chaos", text: "This is Chaos, a large world in the Kuiper Belt, named after the shapeless void that came before everything else, in Greek myth." },
  { rec: "3G", id: "Dziewanna", text: "This is Dziewanna, an icy world on a long, tilted orbit, named after a Slavic goddess of spring and the wild." },
  { rec: "3G", id: "DeeDee", text: "This is DeeDee. When it was found, it was ninety-two times farther from the Sun than Earth — so far away that it was nicknamed DeeDee, for Distant Dwarf." },
  { rec: "3G", id: "Leleākūhonua", text: "This is Leleākūhonua, nicknamed the Goblin. Its orbit stretches out more than two thousand times Earth's distance from the Sun — one of the strange paths that make some astronomers wonder whether a hidden ninth planet is out there." },
  { rec: "3G", id: "Sila", text: "This is Sila and Nunam, two almost equal icy worlds circling each other. For a few years, seen from Earth, they took turns passing in front of one another." },
  { rec: "3G", id: "Lempo", text: "This is Lempo — not one world but three: a close pair circling each other, and a third companion farther out." },
  /*
   * ===== 3H · The Space Dictionary (boardGlossary.js, all 37 terms) =========
   * Spoken when a term's card is opened; the board's region columns are the
   * "Our neighbourhood" terms. Rephrased from each card's `plain` text for
   * the ear, with the same facts.
   */
  { rec: "3H", id: "term:au", text: "An A.U. — an astronomical unit — is the distance from Earth to the Sun: about a hundred and fifty million kilometres. It is the ruler we use for the Solar System. Light crosses it in just over eight minutes, and Neptune is thirty of them away." },
  { rec: "3H", id: "term:lightspeed", text: "Light travels almost three hundred thousand kilometres every second — the fastest anything can go. Fast enough to circle Earth seven and a half times in one second. And still, space is so big that light has to wait." },
  { rec: "3H", id: "term:lighttime", text: "Light takes time to reach us, so every view is a look into the past. You see the Sun as it was eight minutes ago, and Neptune as it was four hours ago. The further you look, the older the light." },
  { rec: "3H", id: "term:lightyear", text: "A light-year is a distance, not a time: how far light travels in one year — about nine and a half trillion kilometres. The nearest star to the Sun is just over four light-years away." },
  { rec: "3H", id: "term:parsec", text: "A parsec is about three and a quarter light-years. As Earth goes round the Sun, a nearby star seems to shift very slightly against the stars far behind it. Measuring that tiny shift is how we first found the distances to the stars." },
  { rec: "3H", id: "term:inner", text: "The inner planets are the four small, rocky worlds closest to the Sun: Mercury, Venus, Earth and Mars. They have solid ground, thin air or none at all, and hardly any moons." },
  { rec: "3H", id: "term:belt", text: "The main asteroid belt is a wide ring of rocky leftovers between Mars and Jupiter. There are millions of rocks — but spread so thinly that spacecraft fly straight through without having to dodge. Jupiter's pull stopped them from ever gathering into a planet." },
  { rec: "3H", id: "term:giants", text: "The giant planets — Jupiter, Saturn, Uranus and Neptune — are huge worlds of gas and ice, with no solid ground to stand on. Every one of them has rings, and dozens of moons." },
  { rec: "3H", id: "term:kuiper", text: "The Kuiper Belt is a thick ring of icy worlds beyond Neptune. It is like the asteroid belt — but far wider, and made mostly of ice. Pluto lives here, along with thousands of others." },
  { rec: "3H", id: "term:plutinos", text: "The Plutinos go round the Sun twice for every three laps of Neptune, in step with Pluto — which is where their name comes from. That rhythm means Neptune is never nearby when they cross its path, so they are never thrown out." },
  { rec: "3H", id: "term:classical", text: "The classical Kuiper Belt is the belt's main crowd, on calm, nearly round orbits that Neptune never disturbed. It is so peaceful out here that many of its worlds are still in pairs, just as they formed." },
  { rec: "3H", id: "term:scattered", text: "The scattered disc is made of worlds that Neptune kicked, long ago, onto long, stretched, tilted orbits. They swing in close to Neptune, then out to hundreds of times Earth's distance from the Sun." },
  { rec: "3H", id: "term:heliosphere", text: "The heliosphere is the Sun's bubble — blown into space by the solar wind. Its edge, the heliopause, is where the Sun's wind meets the gas between the stars, about a hundred and twenty times Earth's distance from the Sun. Both Voyager spacecraft have crossed it." },
  { rec: "3H", id: "term:detached", text: "Detached worlds never come close enough for Neptune to touch them. Something else must have lifted them out there — perhaps a passing star, or perhaps a planet we have not found yet. Sedna is the best known." },
  { rec: "3H", id: "term:oort", text: "The Oort Cloud is a vast, thin shell of icy comets thought to surround the whole Solar System — reaching over a third of the way to the next star. No one has ever seen it directly. We know it is there from the comets that fall in from it." },
  { rec: "3H", id: "term:asteroid", text: "An asteroid is a lump of rock or metal left over from when the planets formed. Most are too small to pull themselves round, so they are shaped like potatoes — from a few metres to a few hundred kilometres across." },
  { rec: "3H", id: "term:nea", text: "A near-Earth asteroid is one whose orbit brings it close to Earth's own path around the Sun. These are the rocks that astronomers watch most carefully." },
  { rec: "3H", id: "term:centaur", text: "A Centaur is an icy body that has drifted in from beyond Neptune and now loops between the giant planets. Part asteroid, part comet — like the half-horse creature of myth. Within a few million years, a giant planet will fling it away." },
  { rec: "3H", id: "term:comet", text: "A comet is a dirty snowball. Far from the Sun, it is a dark, frozen lump. Near the Sun, its ice turns to gas and streams off into a glowing tail — a tail that always points away from the Sun." },
  { rec: "3H", id: "term:tno", text: "A trans-Neptunian object is anything whose orbit lies, on average, beyond Neptune. Pluto is the famous one — and thousands more are known." },
  { rec: "3H", id: "term:dwarf", text: "A dwarf planet is big enough for its own gravity to pull it into a ball — but not big enough to clear its path of other bodies, so it shares its orbit with a crowd. The official five are Ceres, Pluto, Haumea, Makemake and Eris." },
  { rec: "3H", id: "term:rubble", text: "A rubble pile is not one solid rock, but a loose heap of boulders and gravel, held together only by its own weak gravity. Bennu and Ryugu, both sampled by spacecraft, are rubble piles." },
  { rec: "3H", id: "term:trojan", text: "On every planet's orbit, there are two special places — one sixty degrees ahead of the planet, one sixty degrees behind — where the pull of the Sun and the planet balance. A small body there can share the planet's orbit for ever. Jupiter keeps two great swarms there, named after the heroes of the Trojan War." },
  { rec: "3H", id: "term:interstellar", text: "An interstellar object is something that formed around another star, and is only passing through. It moves too fast for the Sun to catch, so it comes in once and leaves for ever. Three are known, and you can watch each one pass, in Space events." },
  { rec: "3H", id: "term:coma", text: "As a comet nears the Sun, its ice turns straight into gas, dragging dust off with it into a glowing cloud — the coma — thousands of times wider than the comet itself. Sunlight then pushes the dust back into a tail. Far out again, it is just a bare, dark rock." },
  { rec: "3H", id: "term:contact", text: "A contact binary is two bodies that drifted together so gently that they stuck, touching at a narrow neck. Arrokoth, visited by New Horizons, is one." },
  { rec: "3H", id: "term:binary", text: "A binary is two bodies of similar weight going round each other. The point they both circle lies in open space between them, so neither one is the other's moon. A triple has a third body circling the pair." },
  { rec: "3H", id: "term:planet-moon", text: "With a planet and its moon, one is much heavier than the other. The point they circle lies inside the planet — for Earth and the Moon, it is deep under the ground. So the planet only wobbles, and the moon does the going round." },
  { rec: "3H", id: "term:tidallock", text: "A tidally locked moon spins exactly once in each orbit, so it always shows the same face. Our Moon does it. And some pairs, like Pluto and Charon, have locked each other — each keeping one face turned to the other." },
  { rec: "3H", id: "term:rings", text: "Rings are countless pieces of ice and rock circling in one thin, flat band. Not only the giant planets have them — so do small worlds, like Chariklo, Haumea and Quaoar." },
  { rec: "3H", id: "term:orbit", text: "An orbit is falling, and always missing. A moon is falling towards its planet the whole time — but it moves sideways so fast that the planet's surface keeps curving away beneath it." },
  { rec: "3H", id: "term:eccentricity", text: "Eccentricity is how stretched an orbit is. Zero is a perfect circle. Close to one is long and thin, like a comet's. The more stretched it is, the more a body speeds up close in, and dawdles far out." },
  { rec: "3H", id: "term:retrograde", text: "Retrograde means going round backwards — against the direction almost everything else in the Solar System turns. Many small moons that were captured by their planets go round this way." },
  { rec: "3H", id: "term:quasisat", text: "Some small rocks share Earth's year, on a slightly different path. They orbit the Sun, not Earth — but seen from Earth, some seem to circle us once a year, and others creep ahead of us and behind us over the centuries, in the shape of a horseshoe." },
  { rec: "3H", id: "term:resonance", text: "A resonance is when two orbits keep a simple rhythm — like two laps to one, or three to two. The regular tugs add up. They can protect an orbit, like Pluto's, or empty one out, like the gaps in the asteroid belt." },
  { rec: "3H", id: "term:albedo", text: "Albedo is how much light a surface throws back. Soot reflects about four per cent, Earth about thirty, and fresh snow about eighty. Most worlds beyond Neptune are darker than you would think." },
  { rec: "3H", id: "term:tholins", text: "Tholins are a reddish-brown gunk, made when sunlight and cosmic rays break apart simple ices like methane, over millions of years. They are why Pluto's dark regions, and most of the far worlds, are red." },
  // ===== 3I · The Beyond Earth card (aboutExperiencePanel.js) =============
  // Spoken when the brand card opens; stops when it closes.
  { rec: "3I", id: "about", text: "Beyond Earth brings the Solar System to you. Everything you see here was made by nature, not by people — no spacecraft, no satellites, no space stations. Just the Sun, the planets and their moons, the asteroids, the comets, and the icy worlds beyond Neptune: six hundred and eighty-four of them, each on its real path, where it really is today. Watch the things that really happen out here, look up any word, and ride with the Sun around the galaxy. Beyond Earth was imagined by Harsh Pandya, and brought to life with the help of A.I. Stay as long as you like. Nothing out here is in a hurry." },
  // ===== 3J · Rings: every ring system and every named ring (round 69, Prompts.md) =====
  { rec: "3J", id: "ring-system:Jupiter", text: "Jupiter has rings too — faint, dark and dusty, nothing like Saturn's. They were only discovered in nineteen seventy-nine, by Voyager 1. They are made of dust, knocked off Jupiter's small inner moons by tiny meteorites." },
  { rec: "3J", id: "ring:Halo Ring", text: "This is the halo ring, the innermost part of Jupiter's rings — a thick, faint cloud of fine dust, lifted above and below the ring by Jupiter's magnetic field." },
  { rec: "3J", id: "ring:Main Ring", text: "This is Jupiter's main ring: narrow, and remarkably thin, fed by dust blasted off the little moons Adrastea and Metis." },
  { rec: "3J", id: "ring:Amalthea Gossamer Ring", text: "This is the Amalthea gossamer ring, a very faint, broad sheet of dust, supplied by the moon Amalthea, and reaching out to its orbit." },
  { rec: "3J", id: "ring:Thebe Gossamer Ring", text: "This is the Thebe gossamer ring — the faintest and farthest of Jupiter's rings, fed by the little moon Thebe." },
  { rec: "3J", id: "ring-system:Saturn", text: "Saturn's rings are the grandest in the Solar System — more than two hundred and seventy thousand kilometres across, yet in most places only about ten metres thick. They are made almost entirely of water ice, from specks of dust to chunks as big as houses." },
  { rec: "3J", id: "ring:D Ring", text: "This is the D ring, Saturn's faint innermost ring — so sparse that its icy grains barely ever touch." },
  { rec: "3J", id: "ring:C Ring", text: "This is the C ring, a broad, see-through part of Saturn's main rings, laced with narrow ringlets and gaps." },
  { rec: "3J", id: "ring:B Ring", text: "This is the B ring — the brightest, widest and densest of all Saturn's rings. In places it is so packed with ice that almost no light gets through." },
  { rec: "3J", id: "ring:A Ring", text: "This is the A ring, the outermost of Saturn's three bright rings. Two little moons, Pan and Daphnis, carve the dark Encke and Keeler gaps inside it." },
  { rec: "3J", id: "ring:F Ring", text: "This is the F ring, narrow and knotted, marking the edge of Saturn's main rings. Two tiny shepherd moons, Prometheus and Pandora, help keep it in line." },
  { rec: "3J", id: "ring:G Ring", text: "This is the G ring, faint and dusty. A tiny moon, Aegaeon, hides inside a bright arc near its inner edge." },
  { rec: "3J", id: "ring:E Ring", text: "This is the E ring — an enormous, misty cloud of tiny ice grains, sprayed out by the geysers of Enceladus." },
  { rec: "3J", id: "ring-system:Uranus", text: "Uranus has thirteen known rings — narrow, dark and tightly packed. They were found in nineteen seventy-seven, when Uranus passed in front of a star, and the starlight blinked off and on before the planet itself arrived." },
  { rec: "3J", id: "ring:Zeta Ring", text: "This is the zeta ring, the innermost of Uranus's rings — a broad, faint haze of dust, reaching down towards the planet." },
  { rec: "3J", id: "ring:6 Ring", text: "This is the six ring, one of Uranus's narrowest — only a few kilometres wide, and as dark as charcoal." },
  { rec: "3J", id: "ring:5 Ring", text: "This is the five ring, a thin, charcoal-grey ringlet among Uranus's tightly packed inner rings." },
  { rec: "3J", id: "ring:4 Ring", text: "This is the four ring — narrow, dark, and sharply separated from its neighbours." },
  { rec: "3J", id: "ring:Alpha Ring", text: "This is the alpha ring, one of Uranus's main narrow rings, with a clean gap on either side." },
  { rec: "3J", id: "ring:Beta Ring", text: "This is the beta ring, a little brighter than its neighbours — though still extremely dark." },
  { rec: "3J", id: "ring:Eta Ring", text: "This is the eta ring, a narrow ring with a fainter, broader skirt of dust around it." },
  { rec: "3J", id: "ring:Gamma Ring", text: "This is the gamma ring, a sharply defined, narrow ring in the crowded middle of Uranus's ring system." },
  { rec: "3J", id: "ring:Delta Ring", text: "This is the delta ring, narrow and dark, with fainter dust spread around it." },
  { rec: "3J", id: "ring:Lambda Ring", text: "This is the lambda ring, a faint band of dust just outside the orbit of the little moon Cordelia." },
  { rec: "3J", id: "ring:Epsilon Ring", text: "This is the epsilon ring, Uranus's brightest and widest. Two tiny shepherd moons, Cordelia and Ophelia, hold it in place — one on each side." },
  { rec: "3J", id: "ring:Nu Ring", text: "This is the nu ring, one of Uranus's two faint outer rings. It looks reddish, like dust." },
  { rec: "3J", id: "ring:Mu Ring", text: "This is the mu ring, the outermost ring of Uranus. It looks blue, like Saturn's E ring — and it is fed by the tiny moon Mab." },
  { rec: "3J", id: "ring-system:Neptune", text: "Neptune's rings are faint and dark, and named after the astronomers who found the planet. The outermost, Adams, holds bright clumps called arcs — which should have smeared out long ago, but haven't." },
  { rec: "3J", id: "ring:Galle Ring", text: "This is the Galle ring, Neptune's innermost — a faint, broad band of dark dust, named after the astronomer who first saw Neptune." },
  { rec: "3J", id: "ring:Le Verrier Ring", text: "This is the Le Verrier ring, a narrow, dark ring, named after the mathematician who predicted where Neptune would be found." },
  { rec: "3J", id: "ring:Lassell Ring", text: "This is the Lassell ring, a broad, faint sheet of dust, named after the astronomer who discovered Triton." },
  { rec: "3J", id: "ring:Arago Ring", text: "This is the Arago ring, a faint ringlet at the outer edge of the Lassell ring." },
  { rec: "3J", id: "ring:Adams Ring", text: "This is the Adams ring, Neptune's outermost, named after one of the two mathematicians who predicted Neptune. It holds bright arcs of dust that stay bunched together." },
  { rec: "3J", id: "ring:Liberté Arc", text: "This is the Liberté arc, one of the bright clumps in Neptune's Adams ring. Arcs like this should spread out all round the ring — something, probably the little moon Galatea, keeps them bunched." },
  { rec: "3J", id: "ring:Egalité Arc", text: "This is the Egalité arc, the brightest part of Neptune's Adams ring — a clump of dust that refuses to spread out." },
  { rec: "3J", id: "ring:Fraternité Arc", text: "This is the Fraternité arc, another of the bright clumps of dust in Neptune's Adams ring." },
  { rec: "3J", id: "ring:Courage Arc", text: "This is the Courage arc, the faintest of the clumps in Neptune's Adams ring — and one that has been fading since Voyager 2 saw it." },
  { rec: "3J", id: "ring-system:Haumea", text: "Haumea's ring was the first ever found around a world beyond Neptune, in twenty seventeen, when Haumea passed in front of a star." },
  { rec: "3J", id: "ring:Haumea's Ring", text: "This is Haumea's ring, narrow and icy. It goes round exactly once for every three spins of Haumea." },
  { rec: "3J", id: "ring-system:Quaoar", text: "Quaoar has two rings, and both break the rules: they circle far beyond the distance where rings should clump together into moons." },
  { rec: "3J", id: "ring:Q2R", text: "This is Quaoar's inner ring, narrow and faint, found in twenty twenty-three." },
  { rec: "3J", id: "ring:Q1R", text: "This is Quaoar's outer ring — more than three times farther out than a ring should be able to survive. By the usual rules, it should have clumped together into a moon." },
  { rec: "3J", id: "ring-system:Chariklo", text: "Chariklo was the first thing that is not a planet found to have rings — two narrow bands, discovered in twenty thirteen, when it passed in front of a star." },
  { rec: "3J", id: "ring:Oiapoque (C1R)", text: "This is Oiapoque, Chariklo's inner ring — the first ring ever found around something that is not a planet. It is named after a river at Brazil's northern border." },
  { rec: "3J", id: "ring:Chuí (C2R)", text: "This is Chuí, Chariklo's fainter outer ring, named after a river at Brazil's southern border." },
  { rec: "3J", id: "ring-system:Chiron", text: "Chiron may have rings of its own — material seen again and again as it passes in front of stars, perhaps gathered from the dust it throws off when it flares up like a comet." },
  { rec: "3J", id: "ring:Chiron inner ring", text: "This is Chiron's inner ring — seen in some passages in front of stars, but not in others, as if it comes and goes." },
  { rec: "3J", id: "ring:Chiron main ring", text: "This is Chiron's main ring, the one seen again and again since twenty eleven." },
  { rec: "3J", id: "ring:Chiron outer ring", text: "This is Chiron's outer ring, the farthest of the three." },
  { rec: "3J", id: "ring:Chiron debris disc", text: "This is not a ring but a haze — a broad disc of material around Chiron, perhaps dust thrown off when it flares up like a comet." },
  // ===== 3K · More named moons and small bodies (round 69, the owner: any vocal welcome) =====
  { rec: "3K", id: "Metis", text: "This is Metis, Jupiter's innermost moon. It races round in about seven hours — faster than Jupiter itself spins — right inside the main ring." },
  { rec: "3K", id: "Adrastea", text: "This is Adrastea, one of Jupiter's smallest moons, only about sixteen kilometres across. Dust knocked off it helps feed Jupiter's main ring." },
  { rec: "3K", id: "Thebe", text: "This is Thebe, a small inner moon of Jupiter. Dust from it spreads out into the faintest of Jupiter's rings." },
  { rec: "3K", id: "Elara", text: "This is Elara, one of the larger moons in Jupiter's Himalia family — a captured rock, far out from the planet." },
  { rec: "3K", id: "Pasiphae", text: "This is Pasiphae, leader of a family of Jupiter's moons that all go round backwards — probably pieces of one captured asteroid." },
  { rec: "3K", id: "Sinope", text: "This is Sinope, one of Jupiter's far-out moons. It goes round backwards, taking about two years for each lap." },
  { rec: "3K", id: "Carme", text: "This is Carme, which gives its name to the largest family of Jupiter's moons — dozens of small rocks, all going round backwards together." },
  { rec: "3K", id: "Ananke", text: "This is Ananke, leader of a family of small moons that circle Jupiter backwards — all probably pieces of one broken rock." },
  { rec: "3K", id: "Themisto", text: "This is Themisto, a small moon of Jupiter that was found in nineteen seventy-five, then lost for twenty-five years, before it was found again." },
  { rec: "3K", id: "Valetudo", text: "This is Valetudo, a tiny moon that goes round Jupiter forwards while its neighbours go backwards — so one day it may crash into one of them." },
  { rec: "3K", id: "Prometheus", text: "This is Prometheus, a shepherd moon. Each time it passes, it pulls streamers of ice out of Saturn's F ring." },
  { rec: "3K", id: "Pandora", text: "This is Pandora, the outer shepherd of Saturn's F ring, working with Prometheus to help keep the ring narrow." },
  { rec: "3K", id: "Atlas", text: "This is Atlas, a little moon just outside Saturn's A ring, with a ridge around its middle that makes it look like a flying saucer." },
  { rec: "3K", id: "Telesto", text: "This is Telesto, one of the travelling companions of the moon Tethys. It rides sixty degrees ahead of Tethys, on the very same orbit." },
  { rec: "3K", id: "Calypso", text: "This is Calypso, Tethys's other companion. It trails sixty degrees behind Tethys, on the very same orbit." },
  { rec: "3K", id: "Helene", text: "This is Helene, a small moon that rides sixty degrees ahead of Dione, sharing its orbit." },
  { rec: "3K", id: "Polydeuces", text: "This is Polydeuces, a tiny moon that trails sixty degrees behind Dione, sharing its orbit." },
  { rec: "3K", id: "Methone", text: "This is Methone, a tiny moon of Saturn so smooth that it looks like an egg." },
  { rec: "3K", id: "Pallene", text: "This is Pallene, a tiny moon of Saturn that leaves a faint ring of dust along its orbit." },
  { rec: "3K", id: "Anthe", text: "This is Anthe, one of the smallest named moons of Saturn, only about two kilometres across." },
  { rec: "3K", id: "Aegaeon", text: "This is Aegaeon, a moonlet less than a kilometre across, hidden inside a bright arc of Saturn's G ring." },
  { rec: "3K", id: "Ymir", text: "This is Ymir, one of the largest of Saturn's Norse moons, going round backwards, far out from the planet." },
  { rec: "3K", id: "Siarnaq", text: "This is Siarnaq, the largest of Saturn's Inuit moons." },
  { rec: "3K", id: "Albiorix", text: "This is Albiorix, the largest of Saturn's Gallic moons." },
  { rec: "3K", id: "Cordelia", text: "This is Cordelia, the innermost moon of Uranus — a shepherd that keeps the inner edge of the epsilon ring sharp." },
  { rec: "3K", id: "Ophelia", text: "This is Ophelia, the shepherd on the outside of Uranus's epsilon ring, keeping its outer edge sharp." },
  { rec: "3K", id: "Portia", text: "This is Portia, the largest of Uranus's crowded inner moons after Puck. Its neighbours are packed so closely that they tug on one another all the time." },
  { rec: "3K", id: "Mab", text: "This is Mab, a tiny moon of Uranus that feeds the faint blue outer ring with dust." },
  { rec: "3K", id: "Cupid", text: "This is Cupid, one of the smallest moons of Uranus, on a crowded orbit. One day, it may collide with its neighbour, Belinda." },
  { rec: "3K", id: "Sycorax", text: "This is Sycorax, the largest of Uranus's far-out moons — reddish, going round backwards, and taking more than three years for each lap." },
  { rec: "3K", id: "Caliban", text: "This is Caliban, a reddish captured moon, circling Uranus backwards, far out." },
  { rec: "3K", id: "Margaret", text: "This is Margaret, the only one of Uranus's far-out moons that goes round forwards." },
  { rec: "3K", id: "Naiad", text: "This is Naiad, Neptune's innermost moon. It weaves up and down around its neighbour Thalassa, in a dance that keeps them from ever colliding." },
  { rec: "3K", id: "Thalassa", text: "This is Thalassa, Neptune's second moon. Naiad weaves above and below it as they go round, so the two never meet." },
  { rec: "3K", id: "Despina", text: "This is Despina, a small moon just inside Neptune's Le Verrier ring, which it may help to shepherd." },
  { rec: "3K", id: "Hippocamp", text: "This is Hippocamp, the smallest of Neptune's inner moons, found in twenty thirteen. It may be a chip knocked off its bigger neighbour, Proteus." },
  { rec: "3K", id: "Neso", text: "This is Neso, one of the most distant moons of any planet. It takes about twenty-seven years to go round Neptune once." },
  { rec: "3K", id: "Halimede", text: "This is Halimede, a captured moon going round Neptune backwards — perhaps once a piece of Nereid." },
  { rec: "3K", id: "Nix", text: "This is Nix, one of Pluto's small moons. It tumbles as it goes round, so a day there would never be the same twice." },
  { rec: "3K", id: "Hydra", text: "This is Hydra, Pluto's outermost moon, covered in almost pure water ice, and spinning fast — about once every ten hours." },
  { rec: "3K", id: "Kerberos", text: "This is Kerberos, a small moon of Pluto that turned out to be two lobes stuck together." },
  { rec: "3K", id: "Styx", text: "This is Styx, the innermost of Pluto's little moons, only about ten kilometres across." },
  { rec: "3K", id: "Weywot", text: "This is Weywot, Quaoar's moon, named after a sky god of the Tongva people — Quaoar's son." },
  { rec: "3K", id: "Actaea", text: "This is Actaea, Salacia's large moon, named after a sea nymph." },
  { rec: "3K", id: "Ilmarë", text: "This is Ilmarë, Varda's moon, named after one of Varda's spirits in Tolkien's legends." },
  { rec: "3K", id: "Xiangliu", text: "This is Xiangliu, the moon of Gonggong, named after a nine-headed serpent who served the water god." },
  { rec: "3K", id: "Hiisi", text: "This is Hiisi, Lempo's close partner. The two circle each other, while a third world, Paha, circles them both." },
  { rec: "3K", id: "Paha", text: "This is Paha, the outer companion in the Lempo triple, circling the close pair from far out." },
  { rec: "3K", id: "Menoetius", text: "This is Menoetius, the partner of Patroclus — two almost equal worlds circling each other as they trail behind Jupiter. The Lucy spacecraft will visit them in twenty thirty-three." },
  { rec: "3K", id: "Alexhelios", text: "This is Alexhelios, one of the two little moons of the dog-bone asteroid Kleopatra, named after Cleopatra's son." },
  { rec: "3K", id: "Cleoselene", text: "This is Cleoselene, Kleopatra's other little moon, named after Cleopatra's daughter." },
  { rec: "3K", id: "Squannit", text: "This is Squannit, the little moon of the near-Earth asteroid Moshup — once known simply as Beta." },
  { rec: "3K", id: "Skamandrios", text: "This is Skamandrios, the small moon of Hektor, the largest of Jupiter's Trojans." },
  { rec: "3K", id: "Queta", text: "This is Queta, the tiny moon of Eurybates, found by the Hubble telescope ahead of the Lucy spacecraft's visit." },
  { rec: "3K", id: "Shaun", text: "This is Shaun, the little moon of the Trojan Polymele, found when the pair passed in front of a star in twenty twenty-two." },
  { rec: "3K", id: "Aten", text: "This is Aten, the first asteroid found with a year shorter than Earth's. The whole Aten family is named after it." },
  { rec: "3K", id: "Apollo", text: "This is Apollo, the asteroid that gives its name to the largest family of near-Earth rocks. It was found in nineteen thirty-two, and it has a small moon." },
  { rec: "3K", id: "Atira", text: "This is Atira, the first asteroid found that stays inside Earth's orbit the whole way round — and it has a moon of its own." },
  { rec: "3K", id: "ʼAylóʼchaxnim", text: "This is Aylo-chaxnim, the first asteroid ever found that stays inside the orbit of Venus the whole way round. Its name comes from the Luiseño people, and means Venus girl." },
  { rec: "3K", id: "Icarus", text: "This is Icarus, an asteroid that swings closer to the Sun than Mercury, scorching hot, and then out past Mars." },
  { rec: "3K", id: "Geographos", text: "This is Geographos, one of the most stretched-out asteroids known — nearly three times longer than it is wide." },
  { rec: "3K", id: "Castalia", text: "This is Castalia, the first asteroid ever imaged by radar. It turned out to be two lumps, stuck together." },
  { rec: "3K", id: "Nereus", text: "This is Nereus, a small, shiny asteroid — one of the easiest places in the Solar System for a spacecraft to reach from Earth." },
  { rec: "3K", id: "Florence", text: "This is Florence, one of the largest asteroids to pass near Earth, with two tiny moons of its own." },
  { rec: "3K", id: "Hathor", text: "This is Hathor, a small, quick asteroid whose year is shorter than ours. It spins once every three and a half hours." },
  { rec: "3K", id: "Eureka", text: "This is Eureka, the first Trojan of Mars ever found — and the parent of a little family of fragments that share its spot." },
  { rec: "3K", id: "Eurybates", text: "This is Eurybates, the first of Jupiter's Trojans that the Lucy spacecraft will visit, in twenty twenty-seven." },
  { rec: "3K", id: "Polymele", text: "This is Polymele, a small, flattened Trojan of Jupiter, with a moon of its own — another of Lucy's targets." },
  { rec: "3K", id: "Leucus", text: "This is Leucus, one of the slowest-spinning objects known. One turn takes about four and a half days. Lucy will fly past it in twenty twenty-eight." },
  { rec: "3K", id: "Orus", text: "This is Orus, one of Jupiter's Trojans, and one of the worlds the Lucy spacecraft is on its way to visit." },
  { rec: "3K", id: "Bienor", text: "This is Bienor, a stretched-out Centaur — perhaps two bodies, stuck together." },
  { rec: "3K", id: "Asbolus", text: "This is Asbolus, a Centaur with a bright, fresh patch on its surface — perhaps a recent crater." },
  { rec: "3K", id: "Nessus", text: "This is Nessus, a Centaur, and one of the reddest objects in the Solar System." },
  { rec: "3K", id: "Hylonome", text: "This is Hylonome, a Centaur near the outer edge of the giant planets, close to where Neptune's pull takes over." },
  { rec: "3K", id: "Euphrosyne", text: "This is Euphrosyne, one of the largest asteroids — dark, with a moon of its own, on a steeply tilted orbit." },
  { rec: "3K", id: "Koronis", text: "This is Koronis, which gives its name to a family of asteroids — the pieces of a world shattered long ago. Ida is one of them." },
  { rec: "3K", id: "Eos", text: "This is Eos, the parent of one of the largest families of asteroids." },
  { rec: "3K", id: "Nysa", text: "This is Nysa, a bright asteroid that gives its name, with Polana, to a crowded complex of asteroid families." },
  { rec: "3K", id: "Polana", text: "This is Polana, a dark asteroid. Its family may be where Bennu and Ryugu came from." },
  { rec: "3K", id: "Xewioso", text: "This is Xewioso, a dwarf planet candidate beyond Neptune, and one of the darkest of these faraway worlds." },
  { rec: "3K", id: "Achlys", text: "This is Achlys, a large world that moves in step with Neptune, just as Pluto does." },
  { rec: "3K", id: "Uni", text: "This is Uni, a large icy world beyond Neptune that seems to be lighter than water." },
  { rec: "3K", id: "Aya", text: "This is Aya, one of the largest worlds beyond Neptune." },
  { rec: "3K", id: "Rumina", text: "This is Rumina, a world of water ice, out in the scattered disc beyond Neptune." },
  { rec: "3K", id: "Ritona", text: "This is Ritona, a dwarf planet candidate beyond Neptune, named after a Gaulish goddess of river crossings." },
  { rec: "3K", id: "Goibniu", text: "This is Goibniu, a dwarf planet candidate beyond Neptune, named after the smith of the gods in Irish legend." },
  { rec: "3K", id: "Manwë", text: "This is Manwë, a two-lobed world beyond Neptune, with a partner, Thorondor, going round it." },
  { rec: "3K", id: "Teharonhiawako", text: "This is Teharonhiawako and its partner Sawiskera — twin brothers in Mohawk legend, and a pair of worlds circling each other in the cold, quiet Kuiper Belt." },
  { rec: "3K", id: "Altjira", text: "This is Altjira, a world beyond Neptune that is probably not one but three." },
  { rec: "3K", id: "Chiminigagua", text: "This is Chiminigagua, a dwarf planet candidate out in the scattered disc, named after the creator of light in the legends of the Muisca people." },
];

/** The line for a body, by its exact name, or null. */
export function narrationFor(id) {
  return NARRATION.find((entry) => entry.id === id) ?? null;
}
